const doc = $input.item.json.body || $input.item.json;
const docId = doc.doc_id || 'DOC-' + Date.now();
const docTitle = doc.doc_title || 'Untitled Document';
const category = doc.category || 'General';
const rawContent = doc.content || '';

// Split document by markdown headings (# and ##)
const lines = rawContent.split('\n');
const chunks = [];
let currentSection = 'Introduction';
let currentText = [];
let chunkIdx = 0;

for (const line of lines) {
  if (line.startsWith('## ') || line.startsWith('# ')) {
    if (currentText.length > 0) {
      const sectionContent = currentText.join('\n').trim();
      if (sectionContent.length > 20) {
        chunks.push({
          doc_id: docId,
          doc_title: docTitle,
          category,
          section_title: currentSection,
          chunk_index: chunkIdx++,
          content: sectionContent
        });
      }
      currentText = [];
    }
    currentSection = line.replace(/^#+\s*/, '').trim();
  } else {
    currentText.push(line);
  }
}

if (currentText.length > 0) {
  const remaining = currentText.join('\n').trim();
  if (remaining.length > 20) {
    chunks.push({
      doc_id: docId,
      doc_title: docTitle,
      category,
      section_title: currentSection,
      chunk_index: chunkIdx++,
      content: remaining
    });
  }
}

return chunks.map(c => ({ json: c }));

const originalQuery = $('Support Query Webhook Trigger').first().json.body || $('Support Query Webhook Trigger').first().json;
const queryText = (originalQuery.query || '').toLowerCase();
const results = $input.all().map(item => item.json);

// Calculate max similarity score
const topSimilarity = results.length > 0 ? Number(results[0].similarity || 0) : 0;

// Check for sensitive escalation keywords
const escalationTriggers = ['cancel my account', 'dispute charge', 'lawyer', 'legal action', 'breach of contract', 'chargeback'];
const hasEscalationKeyword = escalationTriggers.some(trigger => queryText.includes(trigger));

const requiresEscalation = (topSimilarity < 0.70) || hasEscalationKeyword;

return [{
  json: {
    query: originalQuery.query,
    customer_id: originalQuery.customer_id || 'CUST-ANON',
    session_id: originalQuery.session_id || 'SES-' + Date.now(),
    retrieved_chunks: results,
    confidence_score: Number(topSimilarity.toFixed(3)),
    requires_escalation: requiresEscalation,
    escalation_reason: hasEscalationKeyword ? 'Sensitive billing or legal cancellation keyword detected' : (topSimilarity < 0.70 ? 'Low vector retrieval confidence (< 0.70)' : null)
  }
}];

